import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.DkdHrTl_.js";const p=JSON.parse('{"title":"Docs contract","description":"The org-wide documentation standard every 9aia repo follows.","frontmatter":{"title":"Docs contract","description":"The org-wide documentation standard every 9aia repo follows."},"headers":[],"relativePath":"reference/docs-contract.md","filePath":"reference/docs-contract.md"}'),s={name:"reference/docs-contract.md"};function d(n,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="docs-contract" tabindex="-1">Docs contract <a class="header-anchor" href="#docs-contract" aria-label="Permalink to &quot;Docs contract&quot;">​</a></h1><p>The standard every repo in the org follows. Source of truth for the rules: <a href="https://github.com/9aia/workspace/blob/main/AGENTS.md" target="_blank" rel="noreferrer"><code>AGENTS.md</code></a> → <em>Docs contract</em>; this page is the published reference.</p><h2 id="readme-md" tabindex="-1">README.md <a class="header-anchor" href="#readme-md" aria-label="Permalink to &quot;README.md&quot;">​</a></h2><p>Succinct, helpful, clear. What it is + why + quickstart. No crate tables, verb dumps, or status essays — link to <code>AGENTS.md</code> / docs for depth.</p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p>The agent/dev map: layout, commands, rules, boundary, docs pointer, and the awareness blocks (myco / sturn / kuda). Crate and verb tables are allowed but must match source exactly — generated where a generator exists, audited otherwise.</p><h2 id="per-file-skeletons" tabindex="-1">Per-file skeletons <a class="header-anchor" href="#per-file-skeletons" aria-label="Permalink to &quot;Per-file skeletons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Contains</th></tr></thead><tbody><tr><td><code>README.md</code></td><td>name + one-line what → boundary (owns / doesn&#39;t) → status (only if WIP) → quickstart (≤10 lines) → docs links</td></tr><tr><td><code>AGENTS.md</code></td><td>what-it-is → Layout → Commands → Boundary → Rules → Docs pointer → awareness blocks</td></tr></tbody></table><h2 id="docs-site-ia" tabindex="-1">Docs site IA <a class="header-anchor" href="#docs-site-ia" aria-label="Permalink to &quot;Docs site IA&quot;">​</a></h2><p>Every repo carries a <code>docs/</code> worktree — VitePress + Diátaxis.</p><table tabindex="0"><thead><tr><th>Path</th><th>Holds</th></tr></thead><tbody><tr><td><code>index.md</code></td><td>what / why / boundary + quadrant links</td></tr><tr><td><code>tutorials/</code></td><td>learning-oriented paths</td></tr><tr><td><code>how-to/</code></td><td>task-oriented recipes</td></tr><tr><td><code>reference/</code></td><td>GENERATED ONLY — cli / config / crate-api, with a &quot;do not edit&quot; banner</td></tr><tr><td><code>explanation/</code></td><td>design rationale</td></tr></tbody></table><p>Nav order: <strong>Get started → Tutorials → How-to → Reference → Explanation</strong>.</p><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h2><ul><li>Present tense, second person.</li><li>No marketing adjectives; code over prose.</li><li>Tables for enumerations.</li><li>No versions in prose — versions live in pack manifests only.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Generated, not handwritten</strong> — crate maps, CLI references, and config fields come from <code>docs/gen-*.py</code> scripts rendered from source. Repos without generators get them; drift is a bug.</li><li><strong>Status honesty</strong> — &quot;scaffold&quot; / &quot;wip&quot; / &quot;pending&quot; only if true today; verify against code before writing.</li><li><strong>No <code>CHANGELOG.md</code></strong> — git history + tarsi release notes are the changelog; do not add or keep one.</li><li><strong><code>SECURITY.md</code> / <code>CONTRIBUTING.md</code></strong> — house style where the repo ships code.</li><li><strong>Content matters</strong> — audit narrative and structure (what/why/boundary, Diátaxis quadrant purity), not just factual drift.</li></ul><h2 id="ecosystem" tabindex="-1">Ecosystem <a class="header-anchor" href="#ecosystem" aria-label="Permalink to &quot;Ecosystem&quot;">​</a></h2><p><a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a> is the entrypoint — everything installs and updates through tamias packs. The hierarchy reads <strong>packaging → engines → surfaces</strong>.</p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><p>Docs sites deploy to GitHub Pages only for public repos at <code>https://9aia.com/&lt;repo&gt;/</code>. Private repos keep the site source, no deploy.</p>',20)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
